#!/usr/bin/env python3
"""Build eval357 Crescendo results for GLM-5.3-Flash from native runs only (no cross-target fill)."""

from __future__ import annotations

import argparse
import json
import statistics
import sys
from pathlib import Path

_REPO = Path(__file__).resolve().parents[1]
COHORT_PATH = _REPO / "data/v3.15_eval357.enriched.jsonl"
DEFAULT_OUT_DIR = Path("/root/crescendo_baseline_v315_glm53flash")
QWEN_CRESCENDO = Path("/root/crescendo_baseline_v315_qwen37plus/results.jsonl")


def load_jsonl(path: Path) -> dict[str, dict]:
    if not path.is_file():
        return {}
    out: dict[str, dict] = {}
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.strip():
            row = json.loads(line)
            out[row["sample_id"]] = row
    return out


def is_qwen_imputed(row: dict, qwen_by_id: dict[str, dict]) -> bool:
    sid = row.get("sample_id")
    if not sid or sid not in qwen_by_id:
        return False
    if row.get("target_model") != "glm-5.3-flash":
        return False
    g = {k: v for k, v in row.items() if k != "target_model"}
    q = {k: v for k, v in qwen_by_id[sid].items() if k != "target_model"}
    return g == q


def load_cohort() -> list[str]:
    return [
        json.loads(line)["sample_id"]
        for line in COHORT_PATH.read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]


def merge_native(
    cohort: list[str],
    *,
    out_dir: Path,
    extra_sources: list[Path],
) -> tuple[list[dict], list[str]]:
    qwen_by_id = load_jsonl(QWEN_CRESCENDO)
    native: dict[str, dict] = {}

    default_sources = [
        out_dir / "measured" / "results.jsonl",
        out_dir / "native" / "results.jsonl",
        out_dir / "results.jsonl",
        *extra_sources,
    ]
    seen_paths: set[Path] = set()
    for src in default_sources:
        if src in seen_paths or not src.is_file():
            continue
        seen_paths.add(src)
        for sid, row in load_jsonl(src).items():
            if row.get("target_model") != "glm-5.3-flash":
                continue
            if is_qwen_imputed(row, qwen_by_id):
                continue
            native[sid] = row

    ordered = [native[sid] for sid in cohort if sid in native]
    native_ids = [r["sample_id"] for r in ordered]
    return ordered, native_ids


def write_outputs(out_dir: Path, rows: list[dict], native_ids: list[str], cohort_n: int) -> None:
    out_dir.mkdir(parents=True, exist_ok=True)
    out_path = out_dir / "results.jsonl"
    out_path.write_text(
        "\n".join(json.dumps(r, ensure_ascii=False) for r in rows) + ("\n" if rows else ""),
        encoding="utf-8",
    )

    manifest = {
        "created": __import__("datetime").datetime.now().isoformat(timespec="seconds"),
        "out_dir": str(out_dir),
        "cohort_n": cohort_n,
        "glm_native_sample_ids": native_ids,
        "note": "No cross-target imputation; rows identical to Qwen Crescendo are excluded.",
    }
    (out_dir / "native_manifest.json").write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )
    qwen_manifest = out_dir / "qwen_supplement_manifest.json"
    if qwen_manifest.is_file():
        qwen_manifest.unlink()

    if rows:
        succ = sum(1 for r in rows if r.get("best_outcome") == "成功")
        risks = [float(r.get("best_risk_score") or 0) for r in rows]
        summary = {
            "total": len(rows),
            "eval_cohort_n": cohort_n,
            "successes": succ,
            "asr": succ / len(rows),
            "mean_risk": round(statistics.mean(risks), 2),
        }
    else:
        summary = {"total": 0, "eval_cohort_n": cohort_n, "successes": 0, "asr": 0.0, "mean_risk": 0.0}
    (out_dir / "eval_summary.json").write_text(
        json.dumps(summary, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--out-dir", type=Path, default=DEFAULT_OUT_DIR)
    parser.add_argument(
        "--extra-source",
        type=Path,
        action="append",
        default=[],
        help="Additional native results.jsonl paths (repeatable)",
    )
    args = parser.parse_args()
    cohort = load_cohort()
    rows, native_ids = merge_native(cohort, out_dir=args.out_dir, extra_sources=args.extra_source)
    write_outputs(args.out_dir, rows, native_ids, len(cohort))
    print(f"native_rows={len(rows)} cohort={len(cohort)} wrote {args.out_dir / 'results.jsonl'}")
    if len(rows) < len(cohort):
        print(
            f"WARNING: only {len(rows)}/{len(cohort)} native GLM samples; "
            "run full Crescendo GLM before expecting eval357-complete metrics.",
            file=sys.stderr,
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

